"""Generate original vector exercise artwork and the initial XML screen layouts."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'app/src/main/res'
ns='xmlns:android="http://schemas.android.com/apk/res/android"'
def text(value, style='', ident='', extra=''):
    return f'<TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="{value}"'+(f' style="@style/{style}"' if style else '')+(f' android:id="@+id/{ident}"' if ident else '')+f' {extra}/>'
def button(value, ident, primary=False):
    return f'<Button android:id="@+id/{ident}" style="@style/{"PrimaryButton" if primary else "SecondaryButton"}" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="{value}"/>'
def image(height=160):
    return f'<ImageView android:id="@+id/exercise_image" android:layout_width="match_parent" android:layout_height="{height}dp" android:layout_marginTop="12dp" android:layout_marginBottom="12dp" android:scaleType="fitCenter" android:src="@drawable/exercise_default" android:contentDescription="Exercise illustration"/>'
def field(label, ident, input_type, hint, extra=''):
    return text(label,'FieldLabel')+f'<EditText android:id="@+id/{ident}" android:layout_width="match_parent" android:layout_height="wrap_content" android:minHeight="48dp" android:inputType="{input_type}" android:hint="{hint}" android:textSize="16sp" {extra}/>'
def screen(name, content):
    (root/'layout'/name).write_text(f'<?xml version="1.0" encoding="utf-8"?><ScrollView {ns} android:layout_width="match_parent" android:layout_height="match_parent" android:fillViewport="true"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:padding="20dp">'+button('@string/back','back')+text('', 'PageTitle','page_title')+content+'</LinearLayout></ScrollView>',encoding='utf-8')
screen('activity_workout_form.xml',text('Record one exercise with the same reps and weight for each set.',extra='android:textColor="#536A62"')+text('@string/exercise','FieldLabel')+'<Spinner android:id="@+id/exercise_spinner" android:layout_width="match_parent" android:layout_height="52dp" android:contentDescription="Exercise dropdown"/>'+image(130)+text('@string/date','FieldLabel')+button('','date_button')+field('@string/sets','sets','number','e.g. 3')+field('@string/reps','reps','number','e.g. 10')+field('@string/weight','weight','numberDecimal','Leave blank if not recorded')+field('@string/notes','notes','textMultiLine|textCapSentences','How did your workout feel?', 'android:minLines="2" android:gravity="top"')+text('',ident='form_error',extra='android:textColor="#A12B2B" android:visibility="gone" android:accessibilityLiveRegion="polite"')+button('@string/save','save_workout',True)+button('@string/cancel','cancel'))
screen('activity_exercise_form.xml',text('@string/image_help',extra='android:textColor="#536A62"')+image(200)+field('@string/name','exercise_name','textCapWords','e.g. Biceps Curl')+button('@string/choose_image','choose_image')+button('@string/remove_image','remove_image')+button('@string/save_exercise','save_exercise',True)+button('@string/cancel','cancel'))
detail=image(180)+text('','PageTitle','detail_name')+text('',ident='detail_date',extra='android:textColor="#536A62" android:textSize="16sp"')
for label,ident in [('Sets','detail_sets'),('Repetitions per set','detail_reps'),('Weight','detail_weight'),('Notes','detail_notes')]:
    detail+=text(label,'FieldLabel')+text('',ident=ident,extra='android:textSize="20sp" android:textColor="#183E34" android:paddingTop="4dp" android:paddingBottom="8dp"')
screen('activity_detail.xml',detail+button('@string/edit','edit',True)+button('@string/delete','delete'))
history=f'<LinearLayout {ns} android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:padding="20dp">'+text('WORKOUT LOG',extra='android:textColor="#176B5B" android:textStyle="bold" android:letterSpacing="0.12" android:layout_marginTop="16dp" android:layout_marginBottom="12dp"')+text('@string/history_title','PageTitle','page_title')+text('@string/history_subtitle',extra='android:textColor="#536A62" android:textSize="15sp"')+text('',ident='history_count',extra='android:textColor="#536A62" android:paddingTop="18dp" android:paddingBottom="12dp"')+'<FrameLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1"><ListView android:id="@+id/history_list" android:layout_width="match_parent" android:layout_height="match_parent" android:divider="@android:color/transparent" android:dividerHeight="12dp" android:clipToPadding="false" android:paddingBottom="8dp"/><LinearLayout android:id="@+id/empty" android:layout_width="match_parent" android:layout_height="match_parent" android:gravity="center" android:orientation="vertical">'+image(160)+text('@string/empty_title',extra='android:textSize="21sp" android:textStyle="bold" android:gravity="center" android:textColor="#183E34"')+text('@string/empty_body',extra='android:textSize="16sp" android:gravity="center" android:padding="16dp" android:textColor="#536A62"')+'</LinearLayout></FrameLayout>'+button('@string/add_workout','add_workout',True)+text('@string/offline',extra='android:gravity="center" android:textSize="12sp" android:textColor="#536A62" android:padding="8dp"')+'</LinearLayout>'
(root/'layout/activity_history.xml').write_text(history,encoding='utf-8')
row=f'<LinearLayout {ns} android:layout_width="match_parent" android:layout_height="wrap_content" android:minHeight="100dp" android:orientation="horizontal" android:gravity="center_vertical" android:background="@drawable/card"><ImageView android:id="@+id/row_image" android:layout_width="64dp" android:layout_height="64dp" android:layout_marginEnd="12dp" android:importantForAccessibility="no"/><LinearLayout android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:orientation="vertical">'+text('',ident='row_name',extra='android:textSize="18sp" android:textStyle="bold" android:textColor="#183E34"')+text('',ident='row_date',extra='android:textSize="13sp" android:textColor="#536A62" android:paddingTop="4dp"')+text('',ident='row_summary',extra='android:textSize="14sp" android:textColor="#176B5B" android:paddingTop="6dp"')+'</LinearLayout></LinearLayout>'
(root/'layout/row_workout.xml').write_text(row,encoding='utf-8')
# Original diagrams made from vector paths. No external assets or licenses needed.
paths={
 'exercise_default': [('M48,84 L48,116 M63,76 L63,124 M63,100 L137,100 M137,76 L137,124 M152,84 L152,116', '#176B5B',10)],
 'bench_press': [('M40,139 L155,139 M49,139 L49,163 M143,139 L143,163','#536A62',6),('M65,127 L110,127 L132,145 L147,145 M89,127 L89,90 L117,90','#176B5B',9),('M66,77 L142,77 M74,65 L74,89 M134,65 L134,89','#183E34',7)],
 'squat': [('M97,72 L97,106 L68,126 L94,151 M97,106 L129,122 L119,151 M97,80 L69,65 M97,80 L129,65','#176B5B',9),('M48,65 L151,65 M55,53 L55,77 M144,53 L144,77','#183E34',7)],
 'deadlift': [('M103,77 L86,109 L64,139 M86,109 L118,125 L127,149 M99,85 L125,119 M98,85 L83,123','#176B5B',9),('M57,132 L151,132 M65,121 L65,143 M143,121 L143,143','#183E34',7)],
 'push_up': [('M37,143 L165,143','#536A62',4),('M58,105 L114,115 L153,138 M74,109 L64,135 L49,135 M107,114 L98,137 L84,137','#176B5B',9)],
 'shoulder_press': [('M100,76 L100,113 L80,153 M100,113 L121,153 M100,84 L70,84 L70,49 M100,84 L130,84 L130,49','#176B5B',9),('M51,46 L87,46 M56,36 L56,56 M82,36 L82,56 M113,46 L149,46 M118,36 L118,56 M144,36 L144,56','#183E34',6)]
}
heads={'bench_press':(52,124),'squat':(98,48),'deadlift':(112,59),'push_up':(44,98),'shoulder_press':(100,60)}
for name,segments in paths.items():
    body=f'<vector {ns} android:width="200dp" android:height="180dp" android:viewportWidth="200" android:viewportHeight="180"><path android:fillColor="#E8F1E9" android:pathData="M20,10 L180,10 Q194,10 194,24 L194,156 Q194,170 180,170 L20,170 Q6,170 6,156 L6,24 Q6,10 20,10 Z"/>'
    if name in heads:
        x,y=heads[name];body+=f'<path android:fillColor="#176B5B" android:pathData="M{x-10},{y} a10,10 0,1 0,20,0 a10,10 0,1 0,-20,0"/>'
    for path,color,width in segments:
        body+=f'<path android:fillColor="@android:color/transparent" android:strokeColor="{color}" android:strokeWidth="{width}" android:strokeLineCap="round" android:strokeLineJoin="round" android:pathData="{path}"/>'
    (root/'drawable'/f'{name}.xml').write_text(body+'</vector>',encoding='utf-8')
print('Generated XML layouts and six original vector assets.')
